import React, { useState } from 'react';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

function PreShiftForm() {
  const [formData, setFormData] = useState({
    dayOfWeek: new Date().toLocaleDateString('en-US', { weekday: 'long' }),
    date: new Date().toLocaleDateString('en-US'),
    monthlyTraining: '',
    weeklyTraining: '',
    cbkInfo: '',

    // GSS Results - 3x3 grid
    gss_itr_wtd: '',
    gss_itr_mtd: '',
    gss_itr_ytd: '',
    gss_elite_wtd: '',
    gss_elite_mtd: '',
    gss_elite_ytd: '',
    gss_staff_wtd: '',
    gss_staff_mtd: '',
    gss_staff_ytd: '',

    // GXP Stats - 5x3 grid
    gxp_arrivals_am: '',
    gxp_arrivals_pm: '',
    gxp_arrivals_na: '',
    gxp_departures_am: '',
    gxp_departures_pm: '',
    gxp_departures_na: '',
    gxp_stayovers_am: '',
    gxp_stayovers_pm: '',
    gxp_stayovers_na: '',
    gxp_ooo_am: '',
    gxp_ooo_pm: '',
    gxp_ooo_na: '',
    gxp_vr_am: '',
    gxp_vr_pm: '',
    gxp_vr_na: '',

    // Group Arrivals - 2x4 table
    groupArrivals: Array(8).fill(''),

    // In House Groups - 2x4 table
    inHouseGroups: Array(8).fill(''),

    vipArrivals: '',
    ambassadorArrivals: ''
  });

  const handleChange = (field, value) => {
    setFormData({ ...formData, [field]: value });
  };

  const handleArrayChange = (arrayName, index, value) => {
    const newArray = [...formData[arrayName]];
    newArray[index] = value;
    setFormData({ ...formData, [arrayName]: newArray });
  };

  const generatePDF = () => {
    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.getWidth();

    // Title
    doc.setFontSize(18);
    doc.setFont('helvetica', 'bold');
    doc.text('Pre-Shift Form', pageWidth / 2, 15, { align: 'center' });

    // Day and Date
    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    doc.text(`Day: ${formData.dayOfWeek}`, 14, 25);
    doc.text(`Date: ${formData.date}`, pageWidth - 14, 25, { align: 'right' });

    let yPos = 35;

    // Training Topics and CBK Info
    doc.setFontSize(9);
    doc.setFont('helvetica', 'bold');
    doc.text('Monthly Training Topic:', 14, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(formData.monthlyTraining || '_______________', 14, yPos + 5);

    doc.setFont('helvetica', 'bold');
    doc.text('Weekly Training Topic:', 75, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(formData.weeklyTraining || '_______________', 75, yPos + 5);

    doc.setFont('helvetica', 'bold');
    doc.text('CBK Info:', 136, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(formData.cbkInfo || '_______________', 136, yPos + 5);

    yPos += 15;

    // GSS Results Table
    autoTable(doc, {
      startY: yPos,
      head: [['GSS Results', 'WTD', 'MTD', 'YTD']],
      body: [
        ['ITR', formData.gss_itr_wtd, formData.gss_itr_mtd, formData.gss_itr_ytd],
        ['Elite', formData.gss_elite_wtd, formData.gss_elite_mtd, formData.gss_elite_ytd],
        ['Staff', formData.gss_staff_wtd, formData.gss_staff_mtd, formData.gss_staff_ytd]
      ],
      margin: { left: 14, right: pageWidth / 2 + 5 },
      styles: { fontSize: 8, cellPadding: 2 },
      headStyles: { fillColor: [52, 73, 94], halign: 'center' },
      columnStyles: {
        0: { fontStyle: 'bold', cellWidth: 30 }
      }
    });

    // GXP Stats Table
    autoTable(doc, {
      startY: yPos,
      head: [['GXP Stats', 'AM', 'PM', 'NA']],
      body: [
        ['Arrivals', formData.gxp_arrivals_am, formData.gxp_arrivals_pm, formData.gxp_arrivals_na],
        ['Departures', formData.gxp_departures_am, formData.gxp_departures_pm, formData.gxp_departures_na],
        ['Stayovers', formData.gxp_stayovers_am, formData.gxp_stayovers_pm, formData.gxp_stayovers_na],
        ['OOO Rooms', formData.gxp_ooo_am, formData.gxp_ooo_pm, formData.gxp_ooo_na],
        ['VR Rooms', formData.gxp_vr_am, formData.gxp_vr_pm, formData.gxp_vr_na]
      ],
      margin: { left: pageWidth / 2 + 5, right: 14 },
      styles: { fontSize: 8, cellPadding: 2 },
      headStyles: { fillColor: [52, 73, 94], halign: 'center' },
      columnStyles: {
        0: { fontStyle: 'bold', cellWidth: 30 }
      }
    });

    yPos = doc.lastAutoTable.finalY + 10;

    // Group Arrivals Table
    const groupArrivalsRows = [];
    for (let i = 0; i < 4; i++) {
      groupArrivalsRows.push([
        formData.groupArrivals[i] || '',
        formData.groupArrivals[i + 4] || ''
      ]);
    }

    autoTable(doc, {
      startY: yPos,
      head: [['Group Arrivals', '']],
      body: groupArrivalsRows,
      margin: { left: 14, right: pageWidth / 2 + 5 },
      styles: { fontSize: 8, cellPadding: 2 },
      headStyles: { fillColor: [52, 73, 94], halign: 'center' }
    });

    // In House Groups Table
    const inHouseRows = [];
    for (let i = 0; i < 4; i++) {
      inHouseRows.push([
        formData.inHouseGroups[i] || '',
        formData.inHouseGroups[i + 4] || ''
      ]);
    }

    autoTable(doc, {
      startY: yPos,
      head: [['In House Groups', '']],
      body: inHouseRows,
      margin: { left: pageWidth / 2 + 5, right: 14 },
      styles: { fontSize: 8, cellPadding: 2 },
      headStyles: { fillColor: [52, 73, 94], halign: 'center' }
    });

    yPos = doc.lastAutoTable.finalY + 10;

    // VIP Arrivals and Ambassador Arrivals
    doc.setFontSize(9);
    doc.setFont('helvetica', 'bold');
    doc.text('VIP Arrivals:', 14, yPos);
    doc.setFont('helvetica', 'normal');
    const vipLines = doc.splitTextToSize(formData.vipArrivals || '_______________', 85);
    doc.text(vipLines, 14, yPos + 5);

    doc.setFont('helvetica', 'bold');
    doc.text('Ambassador Arrivals:', pageWidth / 2 + 5, yPos);
    doc.setFont('helvetica', 'normal');
    const ambassadorLines = doc.splitTextToSize(formData.ambassadorArrivals || '_______________', 85);
    doc.text(ambassadorLines, pageWidth / 2 + 5, yPos + 5);

    return doc;
  };

  const handleDownload = () => {
    const doc = generatePDF();
    doc.save(`PreShift_${formData.date.replace(/\//g, '-')}.pdf`);
  };

  const handleClear = () => {
    if (window.confirm('Are you sure you want to clear all fields?')) {
      setFormData({
        dayOfWeek: new Date().toLocaleDateString('en-US', { weekday: 'long' }),
        date: new Date().toLocaleDateString('en-US'),
        monthlyTraining: '',
        weeklyTraining: '',
        cbkInfo: '',
        gss_itr_wtd: '',
        gss_itr_mtd: '',
        gss_itr_ytd: '',
        gss_elite_wtd: '',
        gss_elite_mtd: '',
        gss_elite_ytd: '',
        gss_staff_wtd: '',
        gss_staff_mtd: '',
        gss_staff_ytd: '',
        gxp_arrivals_am: '',
        gxp_arrivals_pm: '',
        gxp_arrivals_na: '',
        gxp_departures_am: '',
        gxp_departures_pm: '',
        gxp_departures_na: '',
        gxp_stayovers_am: '',
        gxp_stayovers_pm: '',
        gxp_stayovers_na: '',
        gxp_ooo_am: '',
        gxp_ooo_pm: '',
        gxp_ooo_na: '',
        gxp_vr_am: '',
        gxp_vr_pm: '',
        gxp_vr_na: '',
        groupArrivals: Array(8).fill(''),
        inHouseGroups: Array(8).fill(''),
        vipArrivals: '',
        ambassadorArrivals: ''
      });
    }
  };

  return (
    <div className="main-content">
      <div className="page-header">
        <h1>Pre-Shift Form</h1>
        <p>Fill out the daily pre-shift information</p>
      </div>

      <div style={{ marginBottom: '20px', display: 'flex', gap: '10px' }}>
        <button className="btn btn-primary" onClick={handleDownload}>
          📄 Download PDF
        </button>
        <button className="btn btn-secondary" onClick={handleClear}>
          🗑️ Clear Form
        </button>
      </div>

      <div className="task-section">
        {/* Day and Date */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', marginBottom: '20px' }}>
          <div className="form-group">
            <label>Day of Week</label>
            <input
              type="text"
              className="form-control"
              value={formData.dayOfWeek}
              onChange={(e) => handleChange('dayOfWeek', e.target.value)}
            />
          </div>
          <div className="form-group">
            <label>Date (MM/DD/YYYY)</label>
            <input
              type="text"
              className="form-control"
              value={formData.date}
              onChange={(e) => handleChange('date', e.target.value)}
            />
          </div>
        </div>

        {/* Training Topics and CBK Info */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '20px', marginBottom: '20px' }}>
          <div className="form-group">
            <label>Monthly Training Topic</label>
            <input
              type="text"
              className="form-control"
              value={formData.monthlyTraining}
              onChange={(e) => handleChange('monthlyTraining', e.target.value)}
            />
          </div>
